<template>
  <main class="kvm-page backup-page">
    <header class="page-head"><div><span class="eyebrow">{{ t('eyebrow') }}</span><h1>{{ t('title') }}</h1><p>{{ t('subtitle') }}</p></div><button class="btn role-secondary" :disabled="loading" @click="loadAll">{{ loading ? t('loading') : t('refresh') }}</button></header>
    <div class="backup-callout"><strong>{{ t('mvpTitle') }}</strong><p>{{ t('mvpHelp') }}</p></div>
    <div v-if="error" class="banner error" role="alert">{{ error }}</div>
    <nav class="backup-tabs" role="tablist"><button v-for="tab in tabs" :key="tab.id" role="tab" :aria-selected="active === tab.id" :class="{ active: active === tab.id }" @click="active = tab.id">{{ t(tab.label) }}</button></nav>

    <section v-if="active === 'destination'" class="backup-card">
      <div class="card-head"><div><h2>{{ t('destinationTitle') }}</h2><p>{{ t('destinationHelp') }}</p></div></div>
      <div v-if="!canManage" class="inline-note">{{ t('readOnlyHelp') }}</div><form v-else class="form-grid" @submit.prevent="saveDestination">
        <label>{{ t('destinationName') }}<input v-model.trim="destination.name" required maxlength="80" autocomplete="off"></label>
        <label>{{ t('bucket') }}<input v-model.trim="destination.bucket" required maxlength="63" autocomplete="off"></label>
        <label class="wide">{{ t('endpoint') }}<input v-model.trim="destination.endpoint_url" type="url" placeholder="https://s3.example.com"></label>
        <label>{{ t('region') }}<input v-model.trim="destination.region" required placeholder="us-east-1"></label>
        <label>{{ t('prefix') }}<input v-model.trim="destination.prefix" placeholder="rancher-kvm"></label>
        <label>{{ t('auth') }}<select v-model="destination.auth"><option value="access-key">{{ t('accessKey') }}</option><option value="workload-identity">{{ t('workloadIdentity') }}</option></select></label>
        <template v-if="destination.auth === 'access-key'"><label>{{ t('accessKeyId') }}<input v-model="destination.access_key_id" required autocomplete="off"></label><label>{{ t('secretAccessKey') }}<input v-model="destination.secret_access_key" required type="password" autocomplete="new-password"></label></template>
        <label>{{ t('encryption') }}<select v-model="destination.encryption"><option value="sse-s3">SSE-S3</option><option value="sse-kms">SSE-KMS</option><option value="provider-default">{{ t('providerDefault') }}</option><option value="none">{{ t('none') }}</option></select></label>
        <label v-if="destination.encryption === 'sse-kms'">{{ t('kmsKeyId') }}<input v-model.trim="destination.kms_key_id" required></label>
        <label class="check"><input v-model="destination.path_style" type="checkbox">{{ t('pathStyle') }}</label>
        <p v-if="formMessage" class="wide success" role="status">{{ formMessage }}</p><p v-if="formError" class="wide error-text" role="alert">{{ formError }}</p>
        <div class="wide actions"><button class="btn role-primary" :disabled="saving">{{ saving ? t('saving') : t('saveDestination') }}</button></div>
      </form>
      <div class="destination-list"><h3>{{ t('savedDestinations') }}</h3><div v-if="!destinations.length" class="empty">{{ t('noDestinations') }}</div><article v-for="item in destinations" :key="item.id" class="destination-row"><div><strong>{{ item.name }}</strong><small>{{ item.bucket }} · {{ item.region }} · {{ item.has_credentials ? t('credentialsSaved') : t('workloadIdentity') }}</small></div><div v-if="canManage" class="actions"><button class="btn role-secondary btn-sm" :disabled="busyId === item.id" @click="testDestination(item)">{{ busyId === item.id ? t('testing') : t('testConnection') }}</button><button class="btn role-link btn-sm danger-text" :disabled="busyId === item.id" @click="deleteDestination(item)">{{ pendingDeleteId === item.id ? t('confirmDeleteAction') : t('delete') }}</button></div></article></div>
    </section>

    <section v-else-if="active === 'capture'" class="backup-card">
      <div class="card-head"><div><h2>{{ t('captureTitle') }}</h2><p>{{ t('captureHelp') }}</p></div></div>
      <div v-if="!canManage" class="inline-note">{{ t('readOnlyHelp') }}</div><form v-else class="form-grid" @submit.prevent="startBackup">
        <label>{{ t('destination') }}<select v-model="capture.destination_id" required><option value="">{{ t('selectDestination') }}</option><option v-for="item in destinations" :key="item.id" :value="item.id">{{ item.name }} — {{ item.bucket }}</option></select></label>
        <label>{{ t('host') }}<select v-model="capture.host_id" required @change="loadVms"><option value="">{{ t('selectHost') }}</option><option v-for="host in hosts" :key="host.id" :value="host.id">{{ host.hostname || host.name }}</option></select></label>
        <label class="wide">{{ t('vm') }}<select v-model="capture.vm_name" required :disabled="!capture.host_id || vmsLoading"><option value="">{{ vmsLoading ? t('loadingVms') : t('selectVm') }}</option><option v-for="vm in eligibleVms" :key="vm.name" :value="vm.name">{{ vm.name }} · {{ vm.state || vm.status }}</option></select></label>
        <div class="wide inline-note">{{ t('poweredOffOnly') }}</div>
        <p v-if="jobMessage" class="wide success" role="status">{{ jobMessage }}</p><p v-if="jobError" class="wide error-text" role="alert">{{ jobError }}</p>
        <div class="wide actions"><button class="btn role-primary" :disabled="starting || !eligibleVms.some(vm => vm.name === capture.vm_name)">{{ starting ? t('backupRunning') : t('startBackup') }}</button></div>
      </form>
      <div v-if="job" class="job-card" aria-live="polite"><strong>{{ t('operation') }} · {{ job.status }}</strong><small>{{ jobMessage || t('waitingForHost') }}</small><button v-if="job.status === 'running' || job.status === 'queued'" class="btn role-secondary btn-sm" @click="pollJob">{{ t('refreshProgress') }}</button></div>
    </section>

    <section v-else class="backup-card">
      <div class="card-head"><div><h2>{{ t('archivesTitle') }}</h2><p>{{ t('archivesHelp') }}</p></div></div>
      <div class="archive-list"><div v-if="!backups.length" class="empty">{{ t('noBackups') }}</div><article v-for="item in backups" :key="item.id" class="archive-row"><div><strong>{{ item.vm_name }}</strong><small>{{ item.host_name }} · {{ dateLabel(item.created_at) }} · {{ sizeLabel(item.size_bytes) }}</small><small class="digest">SHA-256: {{ item.sha256 }}</small></div><div class="actions"><a class="btn role-secondary btn-sm" :href="`${apiBase}/backups/${item.id}/download`" target="_blank" rel="noopener">{{ t('download') }}</a><button v-if="canManage" class="btn role-link btn-sm danger-text" @click="deleteBackup(item)">{{ pendingDeleteId === item.id ? t('confirmDeleteAction') : t('delete') }}</button></div></article></div>
      <p class="restore-note">{{ t('restoreNote') }}</p>
    </section>
  </main>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

const apiBase = (process.env.VUE_APP_KVM_API || '/kvm-api').replace(/\/$/, '');
type Host = { id: string; name: string; hostname?: string; status?: string };
type Vm = { name: string; state?: string; status?: string };
type Destination = { id: string; name: string; bucket: string; region: string; has_credentials: boolean };
type Backup = { id: string; vm_name: string; host_name: string; size_bytes: number; sha256: string; created_at: string };

export default defineComponent({
  name: 'KvmBackups',
  data() { return { apiBase, active: 'capture', tabs: [{ id: 'capture', label: 'captureTab' }, { id: 'destination', label: 'destinationTab' }, { id: 'archives', label: 'archivesTab' }], loading: false, saving: false, starting: false, vmsLoading: false, busyId: '', pendingDeleteId: '', error: '', formError: '', formMessage: '', jobError: '', jobMessage: '', canManage: false, destinations: [] as Destination[], hosts: [] as Host[], vms: [] as Vm[], backups: [] as Backup[], job: null as any, pollTimer: 0 as number, destination: { name: '', endpoint_url: '', region: 'us-east-1', bucket: '', prefix: 'rancher-kvm', auth: 'access-key', access_key_id: '', secret_access_key: '', path_style: false, encryption: 'sse-s3', kms_key_id: '' }, capture: { destination_id: '', host_id: '', vm_name: '' } }; },
  computed: { eligibleVms(): Vm[] { return this.vms.filter((vm) => /shut off|shutoff|stopped|off/i.test(`${vm.state || ''} ${vm.status || ''}`)); } },
  mounted() { this.loadAll(); },
  beforeUnmount() { if (this.pollTimer) window.clearInterval(this.pollTimer); },
  methods: {
    t(key: string): string { const translate = (this as any).$store?.getters?.['i18n/t']; return translate ? translate(`kvmManager.backups.${key}`) : key; },
    async request(path: string, options: RequestInit = {}) { const response = await fetch(`${apiBase}${path}`, { credentials: 'include', cache: 'no-store', ...options, headers: { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...(options.headers || {}) } }); const body = response.status === 204 ? null : await response.json().catch(() => ({})); if (!response.ok) throw new Error(body?.detail || `Request failed (${response.status})`); return body; },
    async loadAll() { this.loading = true; this.error = ''; try { const [destinations, hosts, backups, permissions] = await Promise.all([this.request('/backups/destinations'), this.request('/hosts'), this.request('/backups'), this.request('/permissions')]); this.destinations = destinations || []; this.hosts = hosts || []; this.backups = backups || []; this.canManage = Boolean(permissions?.canManageStorage); if (!this.capture.destination_id && this.destinations.length) this.capture.destination_id = this.destinations[0].id; } catch (error) { this.error = (error as Error).message; } finally { this.loading = false; } },
    async saveDestination() { this.saving = true; this.formError = ''; this.formMessage = ''; try { const result = await this.request('/backups/destinations', { method: 'POST', body: JSON.stringify(this.destination) }); this.formMessage = this.t('destinationSaved'); this.destination = { name: '', endpoint_url: '', region: 'us-east-1', bucket: '', prefix: 'rancher-kvm', auth: 'access-key', access_key_id: '', secret_access_key: '', path_style: false, encryption: 'sse-s3', kms_key_id: '' }; await this.loadAll(); this.capture.destination_id = result.id; } catch (error) { this.formError = (error as Error).message; } finally { this.saving = false; } },
    async testDestination(item: Destination) { this.busyId = item.id; this.formError = ''; this.formMessage = ''; try { await this.request(`/backups/destinations/${item.id}/test`, { method: 'POST' }); this.formMessage = `${item.name}: ${this.t('connectionOk')}`; } catch (error) { this.formError = (error as Error).message; } finally { this.busyId = ''; } },
    async deleteDestination(item: Destination) { if (this.pendingDeleteId !== item.id) { this.pendingDeleteId = item.id; return; } this.busyId = item.id; this.formError = ''; try { await this.request(`/backups/destinations/${item.id}`, { method: 'DELETE' }); this.pendingDeleteId = ''; await this.loadAll(); } catch (error) { this.formError = (error as Error).message; } finally { this.busyId = ''; } },
    async loadVms() { this.capture.vm_name = ''; this.vms = []; if (!this.capture.host_id) return; this.vmsLoading = true; this.jobError = ''; try { const result = await this.request(`/hosts/${this.capture.host_id}/cloud-native`); this.vms = result?.vms || []; } catch (error) { this.jobError = (error as Error).message; } finally { this.vmsLoading = false; } },
    async startBackup() { this.starting = true; this.job = null; this.jobError = ''; this.jobMessage = ''; try { this.job = await this.request('/backups/jobs', { method: 'POST', body: JSON.stringify(this.capture) }); this.jobMessage = this.t('waitingForHost'); await this.pollJob(); if (this.pollTimer) window.clearInterval(this.pollTimer); this.pollTimer = window.setInterval(this.pollJob, 3000); } catch (error) { this.jobError = (error as Error).message; } finally { this.starting = false; } },
    async pollJob() { if (!this.job?.job_id) return; try { this.job = await this.request(`/operations/${this.job.job_id}`); const result = this.job.results?.[0]; if (this.job.status === 'succeeded') { this.jobMessage = this.t('backupComplete'); this.jobError = ''; await this.loadAll(); if (this.pollTimer) window.clearInterval(this.pollTimer); } else if (this.job.status === 'failed' || this.job.status === 'partial') { this.jobError = result?.error || this.t('backupFailed'); this.jobMessage = ''; if (this.pollTimer) window.clearInterval(this.pollTimer); } else { this.jobMessage = this.t('operationInProgress'); } } catch (error) { this.jobError = (error as Error).message; } },
    async deleteBackup(item: Backup) { if (this.pendingDeleteId !== item.id) { this.pendingDeleteId = item.id; return; } try { await this.request(`/backups/${item.id}`, { method: 'DELETE' }); this.pendingDeleteId = ''; await this.loadAll(); } catch (error) { this.error = (error as Error).message; } },
    dateLabel(value: string) { return value ? new Date(value).toLocaleString() : '—'; },
    sizeLabel(value: number) { if (!value) return '0 B'; const units = ['B','KiB','MiB','GiB','TiB']; const index = Math.min(Math.floor(Math.log(value) / Math.log(1024)), units.length - 1); return `${(value / (1024 ** index)).toFixed(index ? 1 : 0)} ${units[index]}`; },
  },
});
</script>

<style scoped>
.backup-page{max-width:1120px;margin:0 auto;padding:24px;box-sizing:border-box}.page-head,.card-head,.archive-row,.destination-row{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.page-head{margin-bottom:20px}.page-head h1{margin:4px 0;font-size:25px;font-weight:500}.page-head p,.card-head p{margin:4px 0;color:var(--muted,#929baa)}.eyebrow{font-size:10px;letter-spacing:.08em;font-weight:700;color:var(--muted,#929baa)}.backup-callout,.inline-note{padding:12px 15px;border-left:3px solid var(--primary,#4b91e2);background:color-mix(in srgb,var(--primary,#4b91e2) 9%,var(--body-bg,#252b33));border-radius:4px}.backup-callout p{margin:4px 0 0;color:var(--muted,#929baa);font-size:13px}.backup-tabs{display:flex;gap:6px;margin:18px 0 12px;border-bottom:1px solid var(--border,#394452)}.backup-tabs button{padding:10px 14px;border:0;border-bottom:2px solid transparent;background:none;color:var(--muted,#929baa);cursor:pointer}.backup-tabs button.active{border-bottom-color:var(--primary,#4b91e2);color:var(--body-text,#e5e7eb)}.backup-card{padding:20px;border:1px solid var(--border,#394452);border-radius:7px;background:var(--body-bg,#252b33)}.card-head{margin-bottom:18px}.card-head h2{margin:0;font-size:19px}.card-head p{font-size:13px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px 18px}.form-grid label{display:flex;flex-direction:column;gap:6px;font-size:13px;font-weight:600}.form-grid input,.form-grid select{width:100%;min-height:38px;padding:8px 10px;box-sizing:border-box;border:1px solid var(--border,#4b5563);border-radius:4px;color:var(--body-text,#e5e7eb);background:var(--body-bg,#252b33);font:inherit;font-weight:400}.wide{grid-column:1/-1}.check{flex-direction:row!important;align-items:center}.check input{width:auto}.actions{display:flex;justify-content:flex-end;align-items:center;gap:8px}.success{color:#54c995}.error-text{color:#e16d76}.inline-note{grid-column:1/-1;color:var(--muted,#a2acb9);font-size:12px}.destination-list,.archive-list{margin-top:26px}.destination-list h3{font-size:15px}.destination-row,.archive-row{align-items:center;padding:13px 0;border-top:1px solid var(--border,#394452)}.destination-row strong,.archive-row strong,.destination-row small,.archive-row small{display:block}.destination-row small,.archive-row small{margin-top:5px;color:var(--muted,#929baa);font-size:12px}.archive-row .digest{font-family:monospace;overflow-wrap:anywhere}.empty{padding:18px;color:var(--muted,#929baa);text-align:center}.job-card{display:flex;align-items:center;gap:12px;margin-top:18px;padding:13px;border:1px solid var(--border,#394452);border-radius:5px}.job-card small{flex:1;color:var(--muted,#929baa)}.restore-note{margin-top:18px;padding-top:14px;border-top:1px solid var(--border,#394452);color:var(--muted,#929baa);font-size:12px}.danger-text{color:#df747b}@media(max-width:700px){.backup-page{padding:16px 12px}.page-head,.archive-row,.destination-row{flex-direction:column;align-items:stretch}.form-grid{grid-template-columns:1fr}.wide{grid-column:1}.actions{justify-content:flex-start;flex-wrap:wrap}.job-card{align-items:flex-start;flex-direction:column}.backup-card{padding:15px}}
</style>
